        "hero.slide1.title": "Industrial Safety & Violation Control",
        "hero.slide1.text": "Industrial safety and labor protection, PPE recognition and violation control, emergency detection and equipment operation monitoring",
        "hero.slide2.title": "Human Behavior & Event Analytics",
        "hero.slide2.text": "Monitoring employee engagement, task performance assessment, staff action analysis, theft and suspicious event detection",
        "hero.slide3.title": "Quality Control & Production Automation",
        "hero.slide3.text": "Detection of defects and waste, counting and classification of objects on the conveyor, control of assembly accuracy and production line automation",
        "about.kicker": "About",
        "about.title": "Technologies that see, hear and understand",
        "about.p1": "Statanly Tech Global develops an enterprise AI platform for video and audio analytics, designed for industry, retail, HoReCa, transport infrastructure and corporate process automation.",
        "about.p2": "The company combines expertise in Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps and the development of high-load AI systems for enterprise customers.",
        "about.li1": "More than 400 completed AI projects for large industrial and commercial customers, including metallurgy, energy, manufacturing, retail and hospitality.",
        "about.li2": "A proprietary AI event analytics platform with low-code scenarios, cloud and on-premise architecture, BI analytics and a marketplace of models.",
        "about.li3": "A team of engineers, data scientists and researchers with experience in enterprise AI solutions and leading global AI/ML companies.",
        "about.li4": "Development of industry AI ecosystems that combine ready-made models, Generative AI, VLM and tools for creating new scenarios for specific business needs. The team includes graduates of the world’s leading technical universities.",
        "about.platform.p1": "The company’s core product is a multimodal AI Event Analytics Platform based on Computer Vision, Speech Analytics, Large Language Models (LLM), VLM and Generative AI, designed to build an ecosystem of intelligent models and scenarios for the needs of any industry.",
        "about.platform.p2": "The main idea of the platform is to simplify the creation of new AI scenarios: a user describes a task in natural language, and the system helps turn it into a working scenario for monitoring, detection or event analysis. This may include safety violations, deviations in production processes, personnel actions, product defects, queues, equipment downtime or other non-standard events.",
        "about.platform.p3": "The platform combines video streams, audio data, events and business processes into a unified AI environment. It allows enterprises to use ready-made modules, configure event analytics rules, connect new data sources, fine-tune models and adapt scenarios to a specific facility, enterprise or production process.",
        "about.platform.p4": "The platform powers AI solutions for industrial safety, violation control, workforce efficiency analytics, production analytics, quality control, retail, HoReCa, transport infrastructure and operational process automation.",
