        "malls.page.title": "Soluciones inteligentes de IA para centros comerciales y edificios de oficinas",
        "malls.breadcrumb.current": "Centros comerciales",
        "malls.hero.kicker": "Plataforma de IA para centros comerciales y edificios de oficinas",
        "malls.hero.title": "Plataforma de IA para centros comerciales y edificios de oficinas",
        "malls.hero.subtitle": "Conteo de personas, detección de objetos abandonados, humo e incendios, peleas, conflictos y multitudes en una plataforma unificada de monitorización con IA.",
        "malls.meta.people": "Conteo de personas",
        "malls.meta.flow": "Analítica de flujos y zonas",
        "malls.meta.smoke": "Detección de humo e incendios",
        "malls.meta.conflict": "Detección de peleas y conflictos",
        "malls.meta.objects": "Detección de objetos abandonados",
        "malls.meta.crowd": "Monitorización de multitudes",
        "malls.intro.p1": "La plataforma de IA para centros comerciales transforma las cámaras existentes en un sistema de control operativo en tiempo real para flujos de visitantes, incidentes de seguridad, congestión y calidad del servicio.",
        "malls.intro.p2": "La plataforma detecta formación anómala de multitudes, objetos desatendidos, riesgos de humo e incendio, comportamiento agresivo, peleas, violaciones de zonas de acceso y cuellos de botella de tráfico.",
        "malls.insight.text": "Los grandes espacios públicos aún dependen de vigilancia fragmentada. La plataforma de IA convierte la monitorización de centros comerciales y oficinas en un sistema unificado basado en analítica de visitantes, eventos en tiempo real e inteligencia operativa.",
        "malls.cap.title": "Capacidades de IA para centros comerciales y edificios de oficinas",
        "malls.cap.lead": "La plataforma combina analítica de seguridad, monitorización de flujos de visitantes y detección de incidentes para gestionar atrios, pasillos, entradas, food courts, conexiones de parking y zonas comunes.",
        "malls.cap.people.title": "Conteo de personas y analítica por zonas",
        "malls.cap.people.text": "Conteo en tiempo real por zona, planta, entrada, escaleras mecánicas y pasillos clave con mapas de calor e indicadores de ocupación.",
        "malls.cap.crowd.title": "Densidad de multitudes y congestión",
        "malls.cap.crowd.text": "Detección de zonas saturadas, colas inusuales y congestión cerca de entradas, food courts, ascensores y rutas de evacuación.",
        "malls.cap.conflict.title": "Detección de peleas y conflictos",
        "malls.cap.conflict.text": "Detección automática de comportamiento agresivo, peleas, alteraciones de la multitud y escenarios de escalada para una respuesta de seguridad más rápida.",
        "malls.cap.fire.title": "Humo, fuego y riesgos de seguridad",
        "malls.cap.fire.text": "Detección temprana de humo y fuego abierto en zonas comunes, pasillos de servicio y espacios técnicos con alertas inmediatas.",
        "malls.cap.objects.title": "Objetos abandonados y elementos extraños",
        "malls.cap.objects.text": "Detección de bolsas desatendidas, objetos abandonados y elementos extraños en pasillos, halls y espacios públicos compartidos.",
        "malls.cap.performance.title": "Rendimiento del centro comercial y del edificio",
        "malls.cap.performance.text": "Analítica objetiva de horas pico, ocupación por zona, tráfico junto a locales y utilización de áreas de servicio.",
        "malls.analytics.title": "Analítica y control inteligentes",
        "malls.analytics.text": "Nuestra plataforma de IA convierte vídeo de centros comerciales y edificios en analítica operativa útil para seguridad, facility managers y operadores comerciales.",
        "malls.analytics.b1": "Análisis de flujos de visitantes y horas pico",
