        "beauty.meta.quality": "Calidad del servicio",
        "beauty.intro.p1": "La plataforma para salones de belleza con IA convierte las cámaras existentes en un sistema de control operativo en tiempo real para etapas de servicio, actividad del personal, estándares de higiene, experiencia del cliente y eventos de seguridad.",
        "beauty.intro.p2": "La plataforma detecta retrasos en el servicio, zonas de recepción desatendidas, actividad sospechosa, riesgos de fuego y humo, incumplimientos de higiene, problemas de carga de trabajo del personal y cuellos de botella en la atención al cliente.",
        "beauty.insight.text": "La IA convierte los salones de belleza en entornos de servicio medibles: cada etapa, acción del personal, evento de seguridad e indicador de experiencia del cliente se transforma en datos objetivos para mejorar la calidad.",
        "beauty.cap.kicker": "Capacidades de IA",
        "beauty.cap.title": "Capacidades de IA para salones de belleza",
        "beauty.cap.lead": "La plataforma combina control de calidad del servicio, monitorización de seguridad, prevención de robos, detección de riesgos de incendio, analítica del personal y mejora de la experiencia del cliente en una sola capa operativa.",
        "beauty.cap.service.title": "Monitorización del proceso de servicio",
        "beauty.cap.service.text": "Controle etapas del servicio, tiempo de espera, acciones del personal y fluidez del flujo de clientes en tiempo real.",
        "beauty.cap.safety.title": "Seguridad y cumplimiento",
        "beauty.cap.safety.text": "Monitorice procedimientos de seguridad, estándares de higiene y cumplimiento laboral en las zonas del salón.",
        "beauty.cap.theft.title": "Prevención de robos",
        "beauty.cap.theft.text": "Detecte comportamiento sospechoso, acceso no autorizado, riesgos de inventario y actividad inusual de personal o visitantes.",
        "beauty.cap.fire.title": "Detección de fuego y humo",
        "beauty.cap.fire.text": "Detecte humo temprano, riesgos de incendio y uso inseguro de equipos con alertas instantáneas para gestores.",
        "beauty.cap.staff.title": "Gestión del personal",
        "beauty.cap.staff.text": "Controle asistencia, productividad, distribución de carga, tiempo inactivo y disciplina del servicio.",
        "beauty.cap.quality.title": "Mejora de la calidad del servicio",
        "beauty.cap.quality.text": "Use flujo de clientes, tiempo de servicio y analítica de procesos para aumentar calidad y lealtad.",
        "beauty.analytics.title": "Analítica inteligente e insights",
        "beauty.analytics.text": "La plataforma convierte vídeo y datos operativos en insights accionables que ayudan a propietarios de salones a mejorar la calidad del servicio, reducir riesgos y gestionar equipos objetivamente.",
        "beauty.analytics.b1": "Análisis de flujo de clientes y horas pico",
