        "common.more": "Más",
        "common.readMore": "Leer más",
        "hero.slide1.title": "Seguridad Industrial y Control de Infracciones",
        "hero.slide1.text": "Control de seguridad industrial y protección laboral, reconocimiento de EPI, detección de infracciones, emergencias y monitorización de equipos",
        "hero.slide2.title": "Analítica de Comportamiento y Eventos",
        "hero.slide2.text": "Monitorización de la actividad de empleados, evaluación de tareas, análisis de acciones del personal y detección de robos y eventos sospechosos",
        "hero.slide3.title": "Control de Calidad y Automatización de Producción",
        "hero.slide3.text": "Detección de defectos y desperdicios, conteo y clasificación de objetos en cinta, control de ensamblaje y automatización de la línea",
        "about.kicker": "Sobre",
        "about.title": "Tecnologías que ven, oyen y entienden",
        "about.p1": "Statanly Tech Global desarrolla una plataforma enterprise de IA para analítica de vídeo y audio, diseñada para industria, retail, HoReCa, infraestructura de transporte y automatización de procesos corporativos.",
        "about.p2": "La compañía combina experiencia en Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps y desarrollo de sistemas de IA de alta carga para clientes empresariales.",
        "about.li1": "Más de 400 proyectos de IA completados para grandes clientes industriales y comerciales, incluyendo metalurgia, energía, manufactura, retail y hospitality.",
        "about.li2": "Plataforma propia de analítica de eventos con IA, con escenarios low-code, arquitectura cloud y on-premise, analítica BI y marketplace de modelos.",
        "about.li3": "Equipo de ingenieros, data scientists e investigadores con experiencia en soluciones enterprise de IA y en compañías globales líderes de AI/ML.",
        "about.li4": "Desarrollo de ecosistemas sectoriales de IA que combinan modelos listos, Generative AI, VLM y herramientas para crear nuevos escenarios según necesidades concretas del negocio. El equipo incluye graduados de las mejores universidades técnicas del mundo.",
        "about.platform.p1": "El producto principal de la empresa es una plataforma multimodal de analítica de eventos con IA, basada en visión por computador, analítica de voz, grandes modelos de lenguaje (LLM), VLM e IA generativa, diseñada para crear un ecosistema de modelos inteligentes y escenarios para las necesidades de cualquier industria.",
        "about.platform.p2": "La idea principal de la plataforma es simplificar la creación de nuevos escenarios de IA: el usuario describe una tarea en lenguaje natural y el sistema ayuda a convertirla en un escenario funcional de monitorización, detección o análisis de eventos. Esto puede incluir infracciones de seguridad, desviaciones en procesos productivos, acciones del personal, defectos de producto, colas, paradas de equipos u otros eventos no estándar.",
        "about.platform.p3": "La plataforma combina flujos de vídeo, datos de audio, eventos y procesos de negocio en un entorno unificado de IA. Permite utilizar módulos listos para usar, configurar reglas de analítica de eventos, conectar nuevas fuentes de datos, reentrenar modelos y adaptar escenarios a una instalación, empresa o proceso productivo concreto.",
        "about.platform.p4": "Sobre la base de la plataforma se desarrollan soluciones de IA para seguridad industrial, control de infracciones, análisis de eficiencia del personal, analítica de producción, control de calidad, retail, HoReCa, infraestructura de transporte y automatización de procesos operativos.",
