        "malls.hero.kicker": "Plataforma de IA para centros comerciais e edifícios empresariais",
        "malls.hero.title": "Plataforma de IA para centros comerciais e edifícios empresariais",
        "malls.hero.subtitle": "Contagem de pessoas, deteção de objetos abandonados, fumo e fogo, lutas, conflitos e multidões numa plataforma unificada de monitorização com IA.",
        "malls.meta.people": "Contagem de pessoas",
        "malls.meta.flow": "Analítica de fluxos e zonas",
        "malls.meta.smoke": "Deteção de fumo e fogo",
