        "malls.meta.crowd": "Monitorização de multidões",
        "malls.intro.p1": "A plataforma de IA para centros comerciais transforma câmaras existentes num sistema de controlo operacional em tempo real para fluxos de visitantes, incidentes de segurança, congestionamento e qualidade de serviço.",
        "malls.intro.p2": "A plataforma deteta formação anómala de multidões, objetos desatendidos, riscos de fumo e fogo, comportamento agressivo, lutas, violações de zonas de acesso e gargalos de tráfego.",
        "malls.insight.text": "Grandes espaços públicos ainda dependem de vigilância fragmentada. A plataforma de IA transforma a monitorização de centros comerciais e edifícios num sistema unificado baseado em analítica de visitantes, eventos em tempo real e inteligência operacional.",
        "malls.cap.title": "Capacidades de IA para centros comerciais e edifícios empresariais",
        "malls.cap.lead": "A plataforma combina analítica de segurança, monitorização de fluxos de visitantes e deteção de incidentes para gerir átrios, corredores, entradas, praças de alimentação, ligações a parques e áreas comuns.",
        "malls.cap.people.title": "Contagem de pessoas e analítica por zonas",
        "malls.cap.people.text": "Contagem em tempo real por zona, piso, entrada, escadas rolantes e corredores principais com mapas de calor e indicadores de ocupação.",
        "malls.cap.crowd.title": "Densidade de multidões e congestionamento",
        "malls.cap.crowd.text": "Deteção de áreas sobrelotadas, formação invulgar de filas e congestionamento perto de entradas, praças de alimentação, elevadores e rotas de emergência.",
        "malls.cap.conflict.title": "Deteção de lutas e conflitos",
        "malls.cap.conflict.text": "Deteção automática de comportamento agressivo, lutas, perturbações da multidão e cenários de escalada para resposta de segurança mais rápida.",
        "malls.cap.fire.title": "Fumo, fogo e riscos de segurança",
        "malls.cap.fire.text": "Deteção precoce de fumo e fogo aberto em áreas comuns, corredores de serviço e espaços técnicos com alertas imediatos.",
        "malls.cap.objects.title": "Objetos abandonados e itens estranhos",
        "malls.cap.objects.text": "Deteção de malas desatendidas, objetos abandonados e itens estranhos em corredores, halls e espaços públicos partilhados.",
        "malls.cap.performance.title": "Desempenho do centro comercial e edifício",
