        "beauty.meta.quality": "Qualidade do serviço",
        "beauty.intro.p1": "A plataforma para salões de beleza com IA transforma câmaras existentes num sistema de controlo operacional em tempo real para etapas de serviço, atividade da equipa, padrões de higiene, experiência do cliente e eventos de segurança.",
        "beauty.intro.p2": "A plataforma deteta atrasos no serviço, zonas de receção sem atendimento, atividade suspeita, riscos de fogo e fumo, violações de higiene, problemas de carga da equipa e gargalos na experiência do cliente.",
        "beauty.insight.text": "A IA transforma salões de beleza em ambientes de serviço mensuráveis: cada etapa, ação da equipa, evento de segurança e indicador de experiência do cliente torna-se dado objetivo para melhoria da qualidade.",
        "beauty.cap.kicker": "Capacidades de IA",
