        "beauty.cap.lead": "A plataforma combina controlo da qualidade do serviço, monitorização de segurança, prevenção de furtos, deteção de risco de incêndio, analítica da equipa e melhoria da experiência do cliente numa única camada operacional.",
        "beauty.cap.service.title": "Monitorização do processo de serviço",
        "beauty.cap.service.text": "Acompanhe etapas do serviço, tempo de espera, ações da equipa e fluidez do fluxo de clientes em tempo real.",
        "beauty.cap.safety.title": "Segurança e conformidade",
        "beauty.cap.safety.text": "Monitorize procedimentos de segurança, padrões de higiene e conformidade no local de trabalho em todas as zonas do salão.",
        "beauty.cap.theft.title": "Prevenção de furtos",
        "beauty.cap.theft.text": "Detete comportamento suspeito, acesso não autorizado, riscos de inventário e atividade invulgar de equipa ou visitantes.",
        "beauty.cap.fire.title": "Deteção de fogo e fumo",
        "beauty.cap.fire.text": "Detete fumo precoce, riscos de incêndio e uso inseguro de equipamentos com alertas instantâneos para gestores.",
        "beauty.cap.staff.title": "Gestão da equipa",
        "beauty.cap.staff.text": "Monitorize assiduidade, produtividade, distribuição de carga, tempo ocioso e disciplina de serviço.",
