        "platform.strip.factory.text": "Recolha de dados, anotação, datasets sintéticos, treino de modelos e registo.",
        "platform.strip.scenario.text": "Cria lógica complexa de monitorização e automação a partir de módulos de IA reutilizáveis.",
        "platform.strip.integration.title": "Integração VMS / empresarial",
        "platform.strip.integration.text": "Liga câmaras, VMS, SCADA, ERP, controlo de acesso, BI e APIs.",
        "platform.pipeline.kicker": "Como funciona",
        "platform.pipeline.title": "Da tarefa em linguagem natural ao cenário de IA implementado",
        "platform.pipeline.lead": "A ideia central é simples: o utilizador descreve a tarefa de monitorização em linguagem natural — a plataforma constrói automaticamente o pipeline de IA, prepara dados, cria o cenário e implementa a análise em câmaras e infraestrutura.",
        "platform.pipeline.note": "O utilizador não precisa de experiência em IA: a STATANLY transforma um pedido como “detetar trabalhadores sem capacete” ou “encontrar fumo e fogo” em preparação de dados, criação de modelos, lógica de cenários e implementação.",
        "platform.components.kicker": "Componentes da plataforma",
        "platform.components.title": "Componentes principais da plataforma",
        "platform.components.lead": "A STATANLY não é apenas um conjunto de detetores. É uma camada completa de plataforma para criar e operar análise de eventos com IA em infraestrutura empresarial.",
        "platform.components.multimodal.title": "Análise multimodal de eventos",
        "platform.components.multimodal.text": "Fluxos de vídeo, áudio, sensores e metadados são processados em conjunto para detetar eventos, violações, riscos operacionais e desvios de processo.",
        "platform.components.scenario.text": "Camada de orquestração low-code para zonas, gatilhos, regras, horários, escalonamento, notificações e cenários multi-evento.",
        "platform.components.factory.text": "Ferramentas para recolha de dados, anotação de datasets, geração de exemplos sintéticos, treino de modelos e gestão de versões.",
        "platform.components.llmVlm.title": "Camada LLM / VLM",
        "platform.components.llmVlm.text": "Interface de tarefas em linguagem natural e compreensão visão-linguagem para converter intenção de negócio em cenários e datasets de IA.",
        "platform.common.cloudHub": "Cloud Hub",
        "platform.components.cloudHub.text": "Gestão centralizada de modelos, licenças, cenários, análises, relatórios, operações multi-site e fluxos de implementação.",
        "platform.components.onPrem.title": "Runtime On-Prem",
        "platform.components.onPrem.text": "Processamento local de IA dentro do perímetro empresarial com suporte a GPUs, integração VMS, nós edge e infraestrutura segura.",
        "platform.architecture.kicker": "Arquitetura",
        "platform.architecture.title": "Arquitetura unificada para entradas, processamento de IA e saídas",
        "platform.architecture.lead": "A plataforma liga câmaras, microfones, sensores, VMS e sistemas empresariais existentes numa camada operacional de IA que gera eventos, alertas, relatórios, dashboards e integrações.",
        "platform.factory.title": "Criação e melhoria contínua de modelos de IA",
        "platform.factory.lead": "O AI Factory é o ciclo interno que permite criar novos modelos, melhorar modelos existentes e adaptar análises a ambientes, objetos e ângulos de câmara específicos do cliente.",
        "platform.factory.main.text": "A plataforma combina dados reais, geração sintética, etiquetagem assistida por VLM, treino de modelos e ciclos de feedback num processo repetível para criar novos cenários de IA mais rapidamente.",
        "platform.factory.step1.title": "Recolha de dados",
        "platform.factory.step1.text": "Recolhe exemplos de câmaras, eventos arquivados, dados do cliente e ambientes de teste controlados.",
        "platform.factory.step2.title": "Dados sintéticos",
        "platform.factory.step2.text": "Gera casos raros ou difíceis de capturar para melhorar a robustez e reduzir o tempo de lançamento do modelo.",
        "platform.factory.step3.title": "Etiquetagem VLM",
        "platform.factory.step3.text": "Usa modelos visão-linguagem para compreender objetos, pré-etiquetar e validar datasets.",
        "platform.factory.step4.title": "Treino",
        "platform.factory.step4.text": "Treina e ajusta modelos de IA para eventos, locais, setores e condições de câmara específicos.",
        "platform.factory.step5.title": "Registo de modelos",
        "platform.factory.step5.text": "Armazena versões de modelos, métricas, cenários e configurações de implementação num sistema controlado.",
        "platform.factory.step6.title": "Ciclo de feedback",
        "platform.factory.step6.text": "Usa incidentes reais, falsos positivos e validação do operador para melhorar continuamente os modelos.",
        "platform.usecases.kicker": "Cenários de exemplo",
        "platform.usecases.title": "Cenários típicos de IA criados na plataforma",
        "platform.usecases.lead": "A mesma base da plataforma permite criar cenários simples e complexos de análise de eventos para segurança industrial, operações, logística, retalho, HoReCa e infraestrutura.",
        "platform.usecases.ppe.title": "Deteção de EPI",
        "platform.usecases.ppe.text": "Deteta ausência de capacetes, coletes, máscaras, luvas, óculos e outros equipamentos de proteção obrigatórios.",
        "platform.usecases.violations.title": "Deteção de violações",
        "platform.usecases.violations.text": "Deteta comportamento inseguro, acesso a zonas restritas, violações de perímetro e políticas.",
        "platform.usecases.fire.title": "Deteção de fogo e fumo",
        "platform.usecases.fire.text": "Reconhece fumo, fogo e eventos de emergência em produção, armazéns e espaços públicos.",
        "platform.usecases.phone.title": "Uso de telefone",
        "platform.usecases.phone.text": "Controla o uso de telefone e distrações em zonas industriais ou operacionais proibidas.",
        "platform.usecases.people.title": "Contagem de pessoas",
        "platform.usecases.people.text": "Analisa ocupação, fluxo de clientes, filas, densidade de multidões e carga de trabalho por localização.",
        "platform.usecases.process.title": "Monitorização de processos",
        "platform.usecases.process.text": "Monitoriza equipamentos, processos produtivos, gargalos operacionais e eventos anómalos.",
        "platform.deployment.kicker": "Implementação",
        "platform.deployment.title": "Implementação para infraestrutura empresarial",
        "platform.deployment.lead": "A STATANLY suporta arquiteturas cloud, on-premise seguro, edge e híbridas, permitindo implementar análise de IA num local, numa rede distribuída ou em milhares de câmaras.",
        "platform.deployment.cloud.text": "Gestão centralizada de cenários, modelos, análises, licenças, eventos e relatórios multi-site.",
        "platform.deployment.onPrem.title": "On-Prem",
        "platform.deployment.onPrem.text": "Processamento local dentro da infraestrutura do cliente para soberania de dados e requisitos de segurança empresarial.",
        "platform.deployment.edge.title": "Runtime Edge",
        "platform.deployment.edge.text": "Inferência de IA de baixa latência perto de câmaras ou locais para reduzir tráfego e requisitos de servidor.",
        "platform.deployment.vms.title": "Integração VMS",
        "platform.deployment.vms.text": "Ligação a sistemas de vídeo existentes, câmaras IP, RTSP, ONVIF, fluxos de eventos e metadados.",
        "platform.impact.text": "Impacto da plataforma: criação mais rápida de cenários de IA, análise de eventos unificada em vez de detetores isolados, melhoria contínua dos modelos e implementação escalável em sites empresariais e redes de câmaras.",
        "platform.tags.multimodal": "IA multimodal",
