        "hero.slide1.title": "Segurança Industrial e Controlo de Violações",
        "hero.slide1.text": "Controlo de segurança industrial e proteção laboral, reconhecimento de EPI, deteção de violações, emergências e monitorização de equipamentos",
        "hero.slide2.title": "Analítica de Comportamento e Eventos",
        "hero.slide2.text": "Monitorização da atividade dos colaboradores, avaliação de tarefas, análise de ações da equipa e deteção de roubos e eventos suspeitos",
        "hero.slide3.title": "Controlo de Qualidade e Automação da Produção",
        "hero.slide3.text": "Deteção de defeitos e desperdício, contagem e classificação de objetos no transportador, controlo de montagem e automação da linha",
        "about.kicker": "Sobre",
        "about.title": "Tecnologias que veem, ouvem e compreendem",
        "about.p1": "A Statanly Tech Global desenvolve uma plataforma enterprise de IA para analítica de vídeo e áudio, destinada à indústria, retalho, HoReCa, infraestrutura de transporte e automação de processos corporativos.",
        "about.p2": "A empresa combina experiência em Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps e desenvolvimento de sistemas de IA de alta carga para clientes empresariais.",
        "about.li1": "Mais de 400 projetos de IA concluídos para grandes clientes industriais e comerciais, incluindo metalurgia, energia, manufatura, retalho e hotelaria.",
        "about.li2": "Plataforma própria de analítica de eventos com IA, com cenários low-code, arquitetura cloud e on-premise, analítica BI e marketplace de modelos.",
        "about.li3": "Equipa de engenheiros, data scientists e investigadores com experiência em soluções enterprise de IA e em empresas globais líderes de AI/ML.",
        "about.li4": "Desenvolvimento de ecossistemas setoriais de IA que combinam modelos prontos, Generative AI, VLM e ferramentas para criar novos cenários para necessidades específicas de negócio. A equipa inclui graduados das melhores universidades técnicas do mundo.",
        "about.platform.p1": "O principal produto da empresa é uma plataforma multimodal de análise de eventos com IA, baseada em visão computacional, análise de fala, grandes modelos de linguagem (LLM), VLM e IA generativa, criada para formar um ecossistema de modelos inteligentes e cenários para as necessidades de qualquer setor.",
        "about.platform.p2": "A ideia principal da plataforma é simplificar a criação de novos cenários de IA: o utilizador descreve uma tarefa em linguagem natural e o sistema ajuda a transformá-la num cenário operacional de monitorização, deteção ou análise de eventos. Isto pode incluir violações de segurança, desvios em processos produtivos, ações de colaboradores, defeitos de produto, filas, paragens de equipamento ou outros eventos não padronizados.",
        "about.platform.p3": "A plataforma combina fluxos de vídeo, dados de áudio, eventos e processos de negócio num ambiente unificado de IA. Ela permite usar módulos prontos, configurar regras de análise de eventos, conectar novas fontes de dados, reajustar modelos e adaptar cenários a uma instalação, empresa ou processo produtivo específico.",
        "about.platform.p4": "Com base na plataforma, são desenvolvidas soluções de IA para segurança industrial, controlo de violações, análise da eficiência do pessoal, analítica de produção, controlo de qualidade, retalho, HoReCa, infraestrutura de transporte e automação de processos operacionais.",
