        "horeca.the.ai.powered.hospitality.operations.platform.transforms.existing": "A plataforma de operações de hospitalidade com IA transforma câmeras e processos existentes em um sistema digital unificado para qualidade de serviço, cozinha, desempenho da equipe e experiência do cliente.",
        "horeca.the.platform.helps.businesses.identify.not.only.isolated": "A plataforma ajuda a identificar não apenas incidentes isolados, mas também perdas operacionais ocultas: longas esperas, zonas sobrecarregadas, violações de padrões, ineficiências na cozinha, distrações da equipe e queda da qualidade.",
