        "malls.breadcrumb.current": "Centri commerciali",
        "malls.hero.kicker": "Piattaforma IA per centri commerciali e business center",
        "malls.hero.title": "Piattaforma IA per centri commerciali e business center",
        "malls.hero.subtitle": "Conteggio persone, rilevamento di oggetti abbandonati, fumo e incendio, risse, conflitti e folle in un’unica piattaforma di monitoraggio basata su IA.",
        "malls.meta.people": "Conteggio persone",
        "malls.meta.flow": "Analisi flussi e zone",
        "malls.meta.smoke": "Rilevamento fumo e incendio",
        "malls.meta.conflict": "Rilevamento risse e conflitti",
        "malls.meta.objects": "Rilevamento oggetti abbandonati",
        "malls.meta.crowd": "Monitoraggio folle",
        "malls.intro.p1": "La piattaforma IA per centri commerciali trasforma le telecamere esistenti in un sistema di controllo operativo in tempo reale per flussi di visitatori, incidenti di sicurezza, congestione e qualità del servizio.",
        "malls.intro.p2": "La piattaforma rileva formazione anomala di folle, oggetti incustoditi, rischi di fumo e incendio, comportamento aggressivo, risse, violazioni di zone di accesso e colli di bottiglia del traffico.",
        "malls.insight.text": "I grandi spazi pubblici dipendono ancora da una sorveglianza frammentata. La piattaforma IA trasforma il monitoraggio di centri commerciali e business center in un sistema unificato basato su analisi dei visitatori, eventi in tempo reale e intelligence operativa.",
        "malls.cap.title": "Funzionalità IA per centri commerciali e business center",
        "malls.cap.lead": "La piattaforma combina analisi della sicurezza, monitoraggio dei flussi di visitatori e rilevamento incidenti per gestire atri, corridoi, ingressi, food court, collegamenti parcheggio e aree comuni.",
        "malls.cap.people.title": "Conteggio persone e analisi per zone",
        "malls.cap.people.text": "Conteggio in tempo reale per zona, piano, ingresso, area scale mobili e corridoi principali con heatmap e indicatori di occupazione.",
        "malls.cap.crowd.title": "Densità folle e congestione",
        "malls.cap.crowd.text": "Rilevamento di aree sovraffollate, formazione insolita di code e congestione presso ingressi, food court, ascensori e vie di emergenza.",
        "malls.cap.conflict.title": "Rilevamento risse e conflitti",
        "malls.cap.conflict.text": "Rilevamento automatico di comportamento aggressivo, risse, disturbi della folla e scenari di escalation per una risposta di sicurezza più rapida.",
        "malls.cap.fire.title": "Fumo, incendio e rischi di sicurezza",
        "malls.cap.fire.text": "Rilevamento precoce di fumo e fiamme in aree comuni, corridoi di servizio e spazi tecnici con avvisi immediati.",
        "malls.cap.objects.title": "Oggetti abbandonati e corpi estranei",
        "malls.cap.objects.text": "Rilevamento di borse incustodite, oggetti abbandonati ed elementi estranei in passaggi, hall e spazi pubblici condivisi.",
        "malls.cap.performance.title": "Performance di centro commerciale e business center",
        "malls.cap.performance.text": "Analisi oggettiva di ore di punta, occupazione per zona, traffico vicino ai tenant e utilizzo delle aree di servizio.",
        "malls.analytics.title": "Analisi e controllo intelligenti",
        "malls.analytics.text": "La nostra piattaforma IA trasforma i flussi video di centri commerciali e business center in analisi operative per sicurezza, facility manager e operatori commerciali.",
