        "beauty.hero.subtitle": "Monitoraggio dei processi di servizio e delle procedure di sicurezza, prevenzione di furti e incendi e miglioramento della qualità del servizio con analisi basata su IA.",
        "beauty.meta.service": "Monitoraggio del processo di servizio",
