        "beauty.meta.quality": "Qualità del servizio",
        "beauty.intro.p1": "La piattaforma IA per saloni di bellezza trasforma le telecamere esistenti in un sistema di controllo operativo in tempo reale per fasi del servizio, attività del personale, standard igienici, esperienza cliente ed eventi di sicurezza.",
        "beauty.intro.p2": "La piattaforma rileva ritardi nel servizio, reception non presidiate, attività sospette, rischi di fuoco e fumo, violazioni delle procedure igieniche, problemi di carico del personale e colli di bottiglia nel servizio clienti.",
        "beauty.insight.text": "L’IA trasforma i saloni di bellezza in ambienti di servizio misurabili: ogni fase, azione del personale, evento di sicurezza e indicatore di esperienza cliente diventa dato oggettivo per migliorare la qualità.",
        "beauty.cap.kicker": "Funzionalità IA",
        "beauty.cap.title": "Funzionalità IA per saloni di bellezza",
        "beauty.cap.lead": "La piattaforma combina controllo della qualità del servizio, monitoraggio della sicurezza, prevenzione furti, rilevamento del rischio incendio, analisi del personale e miglioramento dell’esperienza cliente in un unico livello operativo.",
        "beauty.cap.service.title": "Monitoraggio del processo di servizio",
        "beauty.cap.service.text": "Monitora fasi del servizio, tempi di attesa, azioni del personale e fluidità del flusso clienti in tempo reale.",
        "beauty.cap.safety.title": "Sicurezza e conformità",
        "beauty.cap.safety.text": "Monitora procedure di sicurezza, standard igienici e conformità sul lavoro nelle zone del salone.",
        "beauty.cap.theft.title": "Prevenzione furti",
        "beauty.cap.theft.text": "Rileva comportamenti sospetti, accessi non autorizzati, rischi di inventario e attività insolite di personale o visitatori.",
        "beauty.cap.fire.title": "Rilevamento fuoco e fumo",
        "beauty.cap.fire.text": "Rileva fumo precoce, rischi di incendio e uso non sicuro delle attrezzature con avvisi istantanei ai manager.",
        "beauty.cap.staff.title": "Gestione del personale",
        "beauty.cap.staff.text": "Monitora presenze, produttività, distribuzione del carico, tempi di inattività e disciplina del servizio.",
        "beauty.cap.quality.title": "Miglioramento della qualità del servizio",
        "beauty.cap.quality.text": "Usa flusso clienti, tempi di servizio e analisi dei processi per aumentare qualità e fidelizzazione.",
        "beauty.analytics.title": "Analisi intelligenti e insight",
        "beauty.analytics.text": "La piattaforma trasforma video e dati operativi in insight azionabili che aiutano i proprietari dei saloni a migliorare la qualità del servizio, ridurre i rischi e gestire i team in modo oggettivo.",
