        "about.platform.note": "L’utente non ha bisogno di competenze IA: STATANLY trasforma una richiesta in linguaggio naturale in preparazione dei dati, creazione del modello, logica dello scenario e deployment.",
        "platform.pageTitle": "Piattaforma multimodale di analisi degli eventi STATANLY",
        "platform.hero.kicker": "Sistema operativo AI",
        "platform.hero.title": "Piattaforma multimodale di analisi degli eventi",
        "platform.hero.subtitle": "Una piattaforma AI aziendale unificata per creare, addestrare, distribuire e gestire scenari di analisi degli eventi su video, audio, sensori, VMS e sistemi aziendali.",
        "platform.hero.bullet1": "Trasforma moduli CV isolati in un unico livello intelligente di analisi degli eventi",
