        "platform.strip.factory.text": "Raccolta dati, annotazione, dataset sintetici, addestramento e registro dei modelli.",
        "platform.strip.scenario.text": "Crea logiche complesse di monitoraggio e automazione da moduli AI riutilizzabili.",
        "platform.strip.integration.title": "Integrazione VMS / Enterprise",
        "platform.strip.integration.text": "Collega telecamere, VMS, SCADA, ERP, controllo accessi, BI e API.",
        "platform.pipeline.kicker": "Come funziona",
        "platform.pipeline.title": "Dalla richiesta in linguaggio naturale allo scenario AI distribuito",
        "platform.pipeline.lead": "L’idea centrale è semplice: l’utente descrive l’attività di monitoraggio in linguaggio naturale; la piattaforma costruisce automaticamente la pipeline AI, prepara i dati, crea lo scenario e distribuisce l’analisi su telecamere e infrastruttura.",
        "platform.pipeline.note": "L’utente non deve avere competenze AI: STATANLY trasforma richieste come “rileva lavoratori senza casco” o “trova fumo e fuoco” in preparazione dati, creazione del modello, logica dello scenario e deployment.",
        "platform.components.kicker": "Componenti della piattaforma",
        "platform.components.title": "Componenti principali della piattaforma",
        "platform.components.lead": "STATANLY non è solo un insieme di detector. È un livello di piattaforma completo per creare e gestire analisi di eventi AI su infrastruttura enterprise.",
        "platform.components.multimodal.title": "Analisi multimodale degli eventi",
        "platform.components.multimodal.text": "Stream video, audio, sensori e metadati vengono elaborati insieme per rilevare eventi, violazioni, rischi operativi e deviazioni di processo.",
        "platform.components.scenario.text": "Livello di orchestrazione low-code per zone, trigger, regole, pianificazioni, escalation, notifiche e scenari multi-evento.",
        "platform.components.factory.text": "Strumenti per raccogliere dati, annotare dataset, generare esempi sintetici, addestrare modelli e gestire versioni.",
        "platform.components.llmVlm.title": "Livello LLM / VLM",
        "platform.components.llmVlm.text": "Interfaccia in linguaggio naturale e comprensione visione-linguaggio per trasformare l’intento di business in scenari e dataset AI.",
        "platform.common.cloudHub": "Cloud Hub",
        "platform.components.cloudHub.text": "Gestione centralizzata di modelli, licenze, scenari, analytics, report, operazioni multi-sito e workflow di deployment.",
        "platform.components.onPrem.title": "Runtime On-Prem",
        "platform.components.onPrem.text": "Elaborazione AI locale nel perimetro aziendale con supporto per GPU, integrazione VMS, nodi edge e infrastruttura sicura.",
        "platform.architecture.kicker": "Architettura",
        "platform.architecture.title": "Architettura unificata per input, elaborazione AI e output",
        "platform.architecture.lead": "La piattaforma collega telecamere, microfoni, sensori, VMS e sistemi aziendali esistenti in un unico livello operativo AI che genera eventi, alert, report, dashboard e integrazioni.",
        "platform.factory.title": "Creazione e miglioramento continuo dei modelli AI",
        "platform.factory.lead": "AI Factory è il ciclo interno che permette di creare nuovi modelli, migliorare quelli esistenti e adattare l’analisi agli ambienti, oggetti e angoli di ripresa del cliente.",
        "platform.factory.main.text": "La piattaforma combina dati reali, generazione sintetica, labeling assistito da VLM, addestramento dei modelli e feedback loop in un processo ripetibile per creare nuovi scenari AI più rapidamente.",
        "platform.factory.step1.title": "Raccolta dati",
        "platform.factory.step1.text": "Raccoglie esempi da telecamere, eventi archiviati, dati del cliente e ambienti di test controllati.",
        "platform.factory.step2.title": "Dati sintetici",
        "platform.factory.step2.text": "Genera casi rari o difficili da acquisire per migliorare robustezza e ridurre il tempo di lancio del modello.",
        "platform.factory.step3.title": "Labeling VLM",
        "platform.factory.step3.text": "Usa modelli visione-linguaggio per comprendere oggetti, pre-etichettare e validare i dataset.",
        "platform.factory.step4.title": "Addestramento",
        "platform.factory.step4.text": "Addestra e ottimizza modelli AI per eventi, siti, settori e condizioni di camera specifiche.",
        "platform.factory.step5.title": "Registro modelli",
        "platform.factory.step5.text": "Archivia versioni dei modelli, metriche, scenari e configurazioni di deployment in un sistema controllato.",
        "platform.factory.step6.title": "Feedback loop",
        "platform.factory.step6.text": "Usa incidenti reali, falsi positivi e validazione degli operatori per migliorare continuamente i modelli.",
        "platform.usecases.kicker": "Scenari di esempio",
        "platform.usecases.title": "Scenari AI tipici creati sulla piattaforma",
        "platform.usecases.lead": "La stessa base di piattaforma può creare scenari semplici e complessi per sicurezza industriale, operations, logistica, retail, HoReCa e infrastrutture.",
        "platform.usecases.ppe.title": "Rilevamento DPI",
        "platform.usecases.ppe.text": "Rileva caschi, gilet, maschere, guanti, occhiali e altri DPI obbligatori mancanti.",
        "platform.usecases.violations.title": "Rilevamento violazioni",
        "platform.usecases.violations.text": "Rileva comportamenti non sicuri, accesso ad aree riservate, violazioni di perimetro e policy.",
        "platform.usecases.fire.title": "Rilevamento fuoco e fumo",
        "platform.usecases.fire.text": "Riconosce fumo, fuoco ed eventi di emergenza in produzione, magazzini e spazi pubblici.",
        "platform.usecases.phone.title": "Uso del telefono",
        "platform.usecases.phone.text": "Controlla uso del telefono e distrazioni in zone industriali o operative vietate.",
        "platform.usecases.people.title": "Conteggio persone",
