        "platform.deployment.kicker": "Deployment",
        "platform.deployment.title": "Deployment per infrastruttura enterprise",
        "platform.deployment.lead": "STATANLY supporta architetture cloud, on-premise sicure, edge e ibride, consentendo di distribuire analisi AI su un sito, una rete distribuita o migliaia di stream camera.",
        "platform.deployment.cloud.text": "Gestione centralizzata di scenari, modelli, analytics, licenze, eventi e report multi-sito.",
