        "hero.slide1.title": "Sicurezza Industriale e Controllo Violazioni",
        "hero.slide1.text": "Controllo della sicurezza industriale e tutela del lavoro, riconoscimento DPI, rilevamento violazioni, emergenze e monitoraggio attrezzature",
        "hero.slide2.title": "Analisi del Comportamento e degli Eventi",
        "hero.slide2.text": "Monitoraggio dell’attività dei dipendenti, valutazione dei compiti, analisi delle azioni del personale e rilevamento di furti ed eventi sospetti",
        "hero.slide3.title": "Controllo Qualità e Automazione della Produzione",
        "hero.slide3.text": "Rilevamento difetti e scarti, conteggio e classificazione su nastro, controllo assemblaggio e automazione della linea",
        "about.kicker": "Chi siamo",
        "about.title": "Tecnologie che vedono, ascoltano e comprendono",
        "about.p1": "Statanly Tech Global sviluppa una piattaforma enterprise di IA per analisi video e audio, progettata per industria, retail, HoReCa, infrastrutture di trasporto e automazione dei processi aziendali.",
        "about.p2": "L’azienda unisce competenze in Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps e sviluppo di sistemi IA ad alto carico per clienti enterprise.",
        "about.li1": "Oltre 400 progetti IA completati per grandi clienti industriali e commerciali, tra cui metallurgia, energia, produzione, retail e hospitality.",
        "about.li2": "Piattaforma proprietaria di analisi eventi con IA, con scenari low-code, architettura cloud e on-premise, BI analytics e marketplace di modelli.",
        "about.li3": "Team di ingegneri, data scientists e ricercatori con esperienza in soluzioni enterprise di IA e in aziende globali leader AI/ML.",
        "about.li4": "Sviluppo di ecosistemi IA settoriali che combinano modelli pronti, Generative AI, VLM e strumenti per creare nuovi scenari per esigenze specifiche del business. Il team include laureati delle migliori università tecniche del mondo.",
        "about.platform.p1": "Il prodotto principale dell’azienda è una piattaforma multimodale di analisi degli eventi basata su IA, costruita su tecnologie di computer vision, analisi vocale, grandi modelli linguistici (LLM), VLM e IA generativa, progettata per creare un ecosistema di modelli intelligenti e scenari per le esigenze di qualsiasi settore.",
        "about.platform.p2": "L’idea principale della piattaforma è semplificare la creazione di nuovi scenari IA: l’utente descrive un compito in linguaggio naturale e il sistema aiuta a trasformarlo in uno scenario operativo di monitoraggio, rilevamento o analisi degli eventi. Può trattarsi di violazioni della sicurezza, anomalie nei processi produttivi, azioni del personale, difetti di prodotto, code, fermi macchina o altri eventi non standard.",
        "about.platform.p3": "La piattaforma combina flussi video, dati audio, eventi e processi aziendali in un ambiente IA unificato. Consente di utilizzare moduli pronti, configurare regole di analisi degli eventi, collegare nuove fonti di dati, riaddestrare modelli e adattare gli scenari a uno stabilimento, a un’impresa o a un processo produttivo specifico.",
        "about.platform.p4": "Sulla base della piattaforma vengono sviluppate soluzioni IA per sicurezza industriale, controllo delle violazioni, analisi dell’efficienza del personale, analisi della produzione, controllo qualità, retail, HoReCa, infrastrutture di trasporto e automazione dei processi operativi.",
        "products.kicker": "Prodotti",
        "products.title": "Esplora i Nostri Prodotti",
        "products.safety.title": "Sicurezza Industriale e Controllo Violazioni",
        "products.safety.li1": "Controllo della sicurezza industriale e tutela del lavoro",
        "products.safety.li2": "Riconoscimento DPI e rilevamento violazioni",
        "products.safety.li3": "Rilevamento emergenze e monitoraggio attrezzature",
