        "horeca.the.platform.helps.businesses.identify.not.only.isolated": "La piattaforma identifica non solo incidenti isolati, ma anche perdite operative nascoste: lunghe attese, aree sovraccariche, violazioni degli standard, inefficienze in cucina, distrazioni del personale e calo della qualità.",
