        "malls.page.title": "Solutions IA intelligentes pour centres commerciaux et immeubles de bureaux",
        "malls.breadcrumb.current": "Centres commerciaux",
        "malls.hero.kicker": "Plateforme IA pour centres commerciaux et immeubles de bureaux",
        "malls.hero.title": "Plateforme IA pour centres commerciaux et immeubles de bureaux",
        "malls.hero.subtitle": "Comptage de personnes, détection d’objets abandonnés, fumée et incendie, bagarres, conflits et foules dans une plateforme unifiée de surveillance par IA.",
        "malls.meta.people": "Comptage de personnes",
        "malls.meta.flow": "Analyse des flux et zones",
