        "malls.meta.crowd": "Surveillance des foules",
        "malls.intro.p1": "La plateforme IA pour centres commerciaux transforme les caméras existantes en système de contrôle opérationnel temps réel pour flux de visiteurs, incidents de sécurité, congestion et qualité de service.",
        "malls.intro.p2": "La plateforme détecte formation anormale de foules, objets sans surveillance, risques de fumée et feu, comportement agressif, bagarres, violations de zones d’accès et goulets de circulation.",
        "malls.insight.text": "Les grands espaces publics reposent encore sur une surveillance fragmentée. La plateforme IA transforme le monitoring des centres commerciaux et bureaux en système unifié basé sur l’analyse visiteurs, les événements temps réel et l’intelligence opérationnelle.",
        "malls.cap.title": "Capacités IA pour centres commerciaux et immeubles de bureaux",
        "malls.cap.lead": "La plateforme combine analyse de sécurité, suivi des flux visiteurs et détection d’incidents pour gérer atriums, couloirs, entrées, food courts, parkings et espaces communs.",
        "malls.cap.people.title": "Comptage de personnes et analyse par zones",
        "malls.cap.people.text": "Comptage en temps réel par zone, étage, entrée, escalator et couloirs clés avec cartes de chaleur et indicateurs d’occupation.",
        "malls.cap.crowd.title": "Densité de foule et congestion",
        "malls.cap.crowd.text": "Détection de zones surchargées, files inhabituelles et congestion près des entrées, food courts, ascenseurs et voies d’urgence.",
        "malls.cap.conflict.title": "Détection de bagarres et conflits",
        "malls.cap.conflict.text": "Détection automatique de comportements agressifs, bagarres, troubles de foule et scénarios d’escalade pour une réponse sécurité plus rapide.",
        "malls.cap.fire.title": "Fumée, feu et risques de sécurité",
        "malls.cap.fire.text": "Détection précoce de fumée et feu ouvert dans zones communes, couloirs de service et espaces techniques avec alerte immédiate.",
        "malls.cap.objects.title": "Objets abandonnés et éléments étrangers",
        "malls.cap.objects.text": "Détection de sacs sans surveillance, objets abandonnés et éléments étrangers dans passages, halls et espaces publics partagés.",
        "malls.cap.performance.title": "Performance du centre commercial et de l’immeuble",
        "malls.cap.performance.text": "Analyse objective des heures de pointe, occupation par zone, trafic près des enseignes et utilisation des zones de service.",
        "malls.analytics.title": "Analyse et contrôle intelligents",
        "malls.analytics.text": "Notre plateforme IA transforme les flux vidéo des centres commerciaux et immeubles en analyses opérationnelles exploitables pour sécurité, facility managers et opérateurs.",
