        "beauty.hero.title": "Plateforme IA pour salons de beauté",
        "beauty.hero.subtitle": "Surveillance des processus de service et des procédures de sécurité, prévention des vols et incendies, amélioration de la qualité de service grâce à l’analyse IA.",
        "beauty.meta.service": "Suivi du processus de service",
