        "beauty.meta.quality": "Qualité de service",
        "beauty.intro.p1": "La plateforme IA pour salons de beauté transforme les caméras existantes en système de contrôle opérationnel en temps réel pour les étapes de service, l’activité du personnel, les standards d’hygiène, l’expérience client et les événements de sécurité.",
        "beauty.intro.p2": "La plateforme détecte retards de service, zones d’accueil non surveillées, activité suspecte, risques de feu et de fumée, violations des procédures d’hygiène, problèmes de charge du personnel et goulots d’étranglement du service client.",
        "beauty.insight.text": "L’IA transforme les salons de beauté en environnements de service mesurables : chaque étape, action du personnel, événement de sécurité et indicateur d’expérience client devient une donnée objective pour améliorer la qualité.",
        "beauty.cap.kicker": "Capacités IA",
        "beauty.cap.title": "Capacités IA pour salons de beauté",
        "beauty.cap.lead": "La plateforme combine contrôle de la qualité de service, surveillance de la sécurité, prévention des vols, détection du risque incendie, analyse du personnel et amélioration de l’expérience client dans une seule couche opérationnelle.",
        "beauty.cap.service.title": "Suivi du processus de service",
        "beauty.cap.service.text": "Suivez étapes de service, temps d’attente, actions du personnel et fluidité du flux client en temps réel.",
        "beauty.cap.safety.title": "Sécurité et conformité",
        "beauty.cap.safety.text": "Surveillez procédures de sécurité, standards d’hygiène et conformité au travail dans les zones du salon.",
        "beauty.cap.theft.title": "Prévention des vols",
        "beauty.cap.theft.text": "Détectez comportements suspects, accès non autorisés, risques d’inventaire et activité inhabituelle du personnel ou des visiteurs.",
        "beauty.cap.fire.title": "Détection feu et fumée",
        "beauty.cap.fire.text": "Détectez fumée précoce, risques d’incendie et usage dangereux des équipements avec alertes instantanées aux managers.",
        "beauty.cap.staff.title": "Gestion du personnel",
        "beauty.cap.staff.text": "Surveillez présence, productivité, répartition de la charge, temps d’inactivité et discipline de service.",
        "beauty.cap.quality.title": "Amélioration de la qualité de service",
        "beauty.cap.quality.text": "Utilisez flux client, temps de service et analyse des processus pour augmenter qualité et fidélité.",
        "beauty.analytics.title": "Analyse intelligente et insights",
        "beauty.analytics.text": "La plateforme transforme vidéo et données opérationnelles en insights exploitables qui aident les propriétaires de salons à améliorer la qualité de service, réduire les risques et gérer les équipes objectivement.",
        "beauty.analytics.b1": "Analyse du flux client et des heures de pointe",
        "beauty.analytics.b2": "Suivi du temps de service et de l’efficacité",
        "beauty.analytics.b3": "Analyse des performances du personnel",
