        "common.getStarted": "Commencer",
        "common.more": "Plus",
        "common.readMore": "Lire plus",
        "hero.slide1.title": "Sécurité Industrielle et Contrôle des Violations",
        "hero.slide1.text": "Contrôle de la sécurité industrielle et de la protection du travail, reconnaissance des EPI, détection des violations, urgences et surveillance des équipements",
        "hero.slide2.title": "Analyse du Comportement et des Événements",
        "hero.slide2.text": "Suivi de l’activité des employés, évaluation des tâches, analyse des actions du personnel et détection des vols et événements suspects",
        "hero.slide3.title": "Contrôle Qualité et Automatisation de Production",
        "hero.slide3.text": "Détection des défauts et rebuts, comptage et classification sur convoyeur, contrôle d’assemblage et automatisation de ligne",
        "about.kicker": "À propos",
        "about.title": "Des technologies qui voient, entendent et comprennent",
        "about.p1": "Statanly Tech Global développe une plateforme enterprise d’IA pour l’analyse vidéo et audio, destinée à l’industrie, au retail, à l’HoReCa, aux infrastructures de transport et à l’automatisation des processus d’entreprise.",
        "about.p2": "L’entreprise réunit une expertise en Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps et développement de systèmes IA à forte charge pour les clients enterprise.",
        "about.li1": "Plus de 400 projets IA réalisés pour de grands clients industriels et commerciaux, notamment dans la métallurgie, l’énergie, la production, le retail et l’hospitality.",
        "about.li2": "Plateforme propriétaire d’analyse d’événements par IA avec scénarios low-code, architecture cloud et on-premise, BI analytics et marketplace de modèles.",
        "about.li3": "Une équipe d’ingénieurs, data scientists et chercheurs ayant une expérience des solutions IA enterprise et des plus grandes entreprises mondiales d’AI/ML.",
        "about.li4": "Développement d’écosystèmes IA sectoriels combinant modèles prêts à l’emploi, Generative AI, VLM et outils de création de nouveaux scénarios pour les besoins spécifiques des entreprises. L’équipe comprend des diplômés des meilleures universités techniques du monde.",
        "about.platform.p1": "Le produit clé de l’entreprise est une plateforme multimodale d’analyse d’événements par IA, basée sur la vision par ordinateur, l’analyse vocale, les grands modèles de langage (LLM), les VLM et l’IA générative, conçue pour créer un écosystème de modèles intelligents et de scénarios adaptés aux besoins de toute industrie.",
        "about.platform.p2": "L’idée principale de la plateforme est de simplifier la création de nouveaux scénarios d’IA : l’utilisateur formule une tâche en langage naturel, et le système aide à la transformer en scénario opérationnel de surveillance, de détection ou d’analyse d’événements. Il peut s’agir d’infractions aux règles de sécurité, d’écarts dans les processus de production, d’actions du personnel, de défauts produit, de files d’attente, d’arrêts d’équipement ou d’autres événements non standard.",
        "about.platform.p3": "La plateforme combine flux vidéo, données audio, événements et processus métier dans un environnement IA unifié. Elle permet d’utiliser des modules prêts à l’emploi, de configurer des règles d’analyse d’événements, de connecter de nouvelles sources de données, d’affiner les modèles et d’adapter les scénarios à un site, une entreprise ou un processus de production spécifique.",
        "about.platform.p4": "Sur la base de la plateforme, des solutions d’IA sont développées pour la sécurité industrielle, le contrôle des infractions, l’analyse de l’efficacité du personnel, l’analytique de production, le contrôle qualité, le retail, l’HoReCa, les infrastructures de transport et l’automatisation des processus opérationnels.",
