        "horeca.the.ai.powered.hospitality.operations.platform.transforms.existing": "La plateforme IA d’hôtellerie transforme les caméras et processus existants en un système numérique unifié pour la qualité de service, la cuisine, la performance du personnel et l’expérience client.",
        "horeca.the.platform.helps.businesses.identify.not.only.isolated": "La plateforme identifie non seulement les incidents isolés, mais aussi les pertes opérationnelles cachées : longues attentes, zones saturées, non-conformités, inefficacités en cuisine, distractions du personnel et baisse de qualité.",
        "horeca.most.restaurant.operations.are.still.monitored.manually.the": "La plupart des opérations de restaurant sont encore surveillées manuellement. La plateforme IA transforme le service, la cuisine et le personnel en un système piloté par des données objectives, des événements temps réel et des analytics.",
