        "horeca.daily.losses.appear.because.of.inefficient.processes.staff": "Les pertes quotidiennes apparaissent à cause de processus inefficaces, d’erreurs du personnel et d’un manque de contrôle opérationnel objectif. En salle, cela signifie de longs temps d’attente, des tables vides ou sales, des files d’attente et des opportunités d’upsell manquées. En cuisine et en zone de service, cela signifie des retards, des erreurs d’assemblage de commandes, des retours et des pertes de produits. Pour la gestion du personnel, cela signifie du temps d’inactivité, des distractions, des standards incohérents et une répartition inégale de la charge de travail.",
