        "malls.page.title": "Intelligente KI-Lösungen für Einkaufszentren und Bürogebäude",
        "malls.breadcrumb.current": "Einkaufszentren",
        "malls.hero.kicker": "KI-Plattform für Einkaufszentren und Bürogebäude",
        "malls.hero.title": "KI-Plattform für Einkaufszentren und Bürogebäude",
        "malls.hero.subtitle": "Personenzählung, Erkennung zurückgelassener Objekte, Rauch- und Branderkennung, Kampf-, Konflikt- und Crowd-Erkennung in einer einheitlichen KI-Monitoring-Plattform.",
        "malls.meta.people": "Personenzählung",
        "malls.meta.flow": "Fluss- und Zonenanalytik",
        "malls.meta.smoke": "Rauch- und Branderkennung",
        "malls.meta.conflict": "Kampf- und Konflikterkennung",
        "malls.meta.objects": "Erkennung zurückgelassener Objekte",
        "malls.meta.crowd": "Crowd-Monitoring",
        "malls.intro.p1": "Die KI-Plattform für Einkaufszentren verwandelt bestehende Überwachungskameras in ein Echtzeit-Kontrollsystem für Besucherströme, Sicherheitsvorfälle, Stauüberwachung und Servicequalität.",
        "malls.intro.p2": "Die Plattform erkennt anormale Crowd-Bildung, unbeaufsichtigte Objekte, Rauch- und Brandrisiken, aggressives Verhalten, Kämpfe, Zugangsverstöße und Verkehrsengpässe.",
        "malls.insight.text": "Große öffentliche Räume verlassen sich noch immer auf fragmentierte Überwachung. Die KI-Plattform macht Monitoring von Einkaufszentren und Bürogebäuden zu einem einheitlichen System aus Besucheranalytik, Echtzeitereignissen und operativer Intelligenz.",
        "malls.cap.title": "KI-Funktionen für Einkaufszentren und Bürogebäude",
        "malls.cap.lead": "Die Plattform kombiniert Sicherheitsanalytik, Besucherfluss-Monitoring und Incident-Erkennung zur Verwaltung von Atrien, Korridoren, Eingängen, Food Courts, Parkverbindungen und Gemeinschaftsflächen.",
        "malls.cap.people.title": "Personenzählung und Zonenanalytik",
        "malls.cap.people.text": "Echtzeitzählung nach Zone, Etage, Eingang, Rolltreppenbereich und Hauptkorridoren mit Heatmaps und Belegungsindikatoren.",
        "malls.cap.crowd.title": "Crowd-Dichte und Stauerkennung",
        "malls.cap.crowd.text": "Erkennung überfüllter Bereiche, ungewöhnlicher Warteschlangen und Staus an Eingängen, Food Courts, Aufzügen und Notwegen.",
        "malls.cap.conflict.title": "Kampf- und Konflikterkennung",
        "malls.cap.conflict.text": "Automatische Erkennung von aggressivem Verhalten, Kämpfen, Crowd-Störungen und Eskalationsszenarien für schnellere Sicherheitsreaktion.",
        "malls.cap.fire.title": "Rauch, Feuer und Sicherheitsrisiken",
        "malls.cap.fire.text": "Früherkennung von Rauch und offenem Feuer in Gemeinschaftsbereichen, Servicekorridoren und Technikräumen mit sofortiger Alarmierung.",
        "malls.cap.objects.title": "Zurückgelassene und fremde Objekte",
        "malls.cap.objects.text": "Erkennung unbeaufsichtigter Taschen, zurückgelassener Objekte und fremder Gegenstände in Laufwegen, Hallen und öffentlichen Bereichen.",
        "malls.cap.performance.title": "Performance von Einkaufszentrum und Bürogebäude",
        "malls.cap.performance.text": "Objektive Analytik für Spitzenzeiten, Belegung nach Zone, Verkehr nahe Mietern und Nutzung von Servicebereichen.",
        "malls.analytics.title": "Intelligente Analytik und Kontrolle",
        "malls.analytics.text": "Unsere KI-Plattform verwandelt Videoströme aus Einkaufszentren und Bürogebäuden in nutzbare operative Analytik für Sicherheitsteams, Facility Manager und Betreiber.",
        "malls.analytics.b1": "Analyse von Besucherfluss und Spitzenzeiten",
