        "malls.platform.kicker": "Plattformbasis",
        "malls.platform.title": "Enterprise-KI-Plattform für öffentliche Räume",
        "malls.platform.lead": "Über einzelne Szenarien hinaus umfasst die Lösung die vollständige STATANLY AI Platform: Modulbibliothek, Szenario-Engine, zentrale Dashboards und hybride Bereitstellung.",
        "malls.platform.modules.title": "KI-Modulbibliothek",
        "malls.platform.modules.text": "Einsatzbereite CV-Szenarien für Personenzählung, Sicherheitsvorfälle, Monitoring, Branderkennung und Facility-Analytik.",
        "malls.platform.scenario.title": "No-Code-Szenario-Engine",
