        "malls.platform.deploy.title": "Cloud · On-Premise · Hybrid",
        "malls.platform.deploy.text": "Flexible Architektur für lokale Verarbeitung, zentralisiertes Monitoring und Multi-Standort-Rollouts.",
        "malls.impact.text": "Business Impact: höhere Besuchersicherheit, schnellere Incident-Reaktion, bessere Crowd-Kontrolle, geringere operative Risiken und eine einheitliche KI-gestützte Managementebene.",
