        "beauty.breadcrumb": "Beauty",
        "beauty.hero.kicker": "KI-Plattform für Schönheitssalons",
        "beauty.hero.title": "KI-Plattform für Schönheitssalons",
        "beauty.hero.subtitle": "Überwachung von Serviceprozessen und Sicherheitsverfahren, Prävention von Diebstahl und Bränden sowie Verbesserung der Servicequalität mit KI-gestützter Analytik.",
        "beauty.meta.service": "Monitoring von Serviceprozessen",
        "beauty.meta.safety": "Sicherheitsverfahren",
        "beauty.meta.theft": "Diebstahlprävention",
        "beauty.meta.fire": "Erkennung von Brandrisiken",
        "beauty.meta.staff": "Personalmanagement",
        "beauty.meta.quality": "Servicequalität",
        "beauty.intro.p1": "Die KI-gestützte Plattform für Schönheitssalons verwandelt bestehende Kameras in ein Echtzeit-Kontrollsystem für Servicephasen, Personalaktivität, Hygienestandards, Kundenerlebnis und Sicherheitsereignisse.",
        "beauty.intro.p2": "Die Plattform erkennt Serviceverzögerungen, unbeaufsichtigte Empfangsbereiche, verdächtige Aktivitäten, Feuer- und Rauchrisiken, Verstöße gegen Hygieneabläufe, Probleme der Personalauslastung und Engpässe im Kundenservice.",
        "beauty.insight.text": "KI macht Schönheitssalons zu messbaren Serviceumgebungen: jede Servicephase, Personalhandlung, jedes Sicherheitsereignis und jeder Indikator des Kundenerlebnisses wird zu objektiven Daten für Qualitätsverbesserung.",
        "beauty.cap.kicker": "KI-Funktionen",
        "beauty.cap.title": "KI-Funktionen für Schönheitssalons",
        "beauty.cap.lead": "Die Plattform kombiniert Servicequalitätskontrolle, Sicherheitsmonitoring, Diebstahlprävention, Erkennung von Brandrisiken, Personalanalytik und Verbesserung des Kundenerlebnisses in einer operativen Ebene.",
        "beauty.cap.service.title": "Monitoring von Serviceprozessen",
        "beauty.cap.service.text": "Verfolgen Sie Servicephasen, Wartezeiten, Personalhandlungen und die reibungslose Kundenbewegung in Echtzeit.",
        "beauty.cap.safety.title": "Sicherheit & Compliance",
        "beauty.cap.safety.text": "Überwachen Sie Sicherheitsverfahren, Hygienestandards und Arbeitsplatz-Compliance in Salonbereichen.",
        "beauty.cap.theft.title": "Diebstahlprävention",
        "beauty.cap.theft.text": "Erkennen Sie verdächtiges Verhalten, unbefugten Zugang, Inventarrisiken und ungewöhnliche Aktivität von Personal oder Besuchern.",
        "beauty.cap.fire.title": "Feuer- und Raucherkennung",
