        "about.platform.note": "Nutzer benötigen keine KI-Expertise: STATANLY verwandelt eine Anfrage in natürlicher Sprache in Datenaufbereitung, Modellerstellung, Szenarienlogik und Deployment.",
        "platform.pageTitle": "STATANLY Multimodale Event-Analytics-Plattform",
        "platform.hero.kicker": "KI-Betriebssystem",
        "platform.hero.title": "Multimodale Event-Analytics-Plattform",
        "platform.hero.subtitle": "Eine einheitliche Enterprise-KI-Plattform zum Erstellen, Trainieren, Bereitstellen und Verwalten von Event-Analytics-Szenarien über Video, Audio, Sensoren, VMS und Unternehmenssysteme.",
        "platform.hero.bullet1": "Verwandelt einzelne CV-Module in eine intelligente Event-Analytics-Schicht",
        "platform.hero.bullet2": "Kombiniert Computer Vision, Sprachanalyse, LLM, VLM, generative KI und Low-Code-Szenario-Orchestrierung",
        "platform.hero.bullet3": "Ermöglicht die Erstellung neuer KI-Szenarien aus Aufgabenbeschreibungen in natürlicher Sprache",
        "platform.hero.card.videoAudio.title": "Video + Audio",
        "platform.hero.card.videoAudio.text": "Multimodale Analyse für Ereignisse, Verstöße und Betriebsprozesse",
        "platform.hero.card.genaiVlm.title": "GenAI + VLM",
