        "platform.common.scenarioEngine": "Szenario-Engine",
        "platform.hero.card.scenario.text": "Low-Code-Regeln, Workflows und operative Automatisierung",
        "platform.hero.card.cloudOnPrem.title": "Cloud / On-Prem",
        "platform.hero.card.cloudOnPrem.text": "Hybride Architektur für Enterprise-Deployment",
        "platform.strip.models.title": "KI-Modellbibliothek",
        "platform.strip.models.text": "Fertige Module für Sicherheit, Verhalten, Betrieb, Qualität und Industrieszenarien.",
        "platform.common.aiFactory": "AI Factory",
        "platform.strip.factory.text": "Datenerfassung, Annotation, synthetische Datensätze, Modelltraining und Registry.",
        "platform.strip.scenario.text": "Erstellt komplexe Monitoring- und Automatisierungslogik aus wiederverwendbaren KI-Modulen.",
        "platform.strip.integration.title": "VMS- / Enterprise-Integration",
        "platform.strip.integration.text": "Verbindet Kameras, VMS, SCADA, ERP, Zutrittskontrolle, BI und APIs.",
        "platform.pipeline.kicker": "Funktionsweise",
        "platform.pipeline.title": "Von der Aufgabe in natürlicher Sprache zum bereitgestellten KI-Szenario",
        "platform.pipeline.lead": "Die Kernidee ist einfach: Der Nutzer beschreibt die Monitoring-Aufgabe in natürlicher Sprache — die Plattform baut automatisch die KI-Pipeline, bereitet Daten vor, erstellt das Szenario und stellt die Analyse auf Kameras und Infrastruktur bereit.",
        "platform.pipeline.note": "Der Nutzer braucht keine KI-Expertise: STATANLY verwandelt Anfragen wie „Arbeiter ohne Helm erkennen“ oder „Rauch und Feuer finden“ in Datenvorbereitung, Modellerstellung, Szenariologik und Deployment.",
        "platform.components.kicker": "Plattformkomponenten",
        "platform.components.title": "Kernkomponenten der Plattform",
        "platform.components.lead": "STATANLY ist nicht nur eine Sammlung von Detektoren. Es ist eine vollständige Plattformschicht zur Erstellung und zum Betrieb von KI-Event-Analytics in Enterprise-Infrastrukturen.",
        "platform.components.multimodal.title": "Multimodale Event-Analytics",
        "platform.components.multimodal.text": "Video-, Audio-, Sensor- und Metadatenströme werden gemeinsam verarbeitet, um Ereignisse, Verstöße, Betriebsrisiken und Prozessabweichungen zu erkennen.",
        "platform.components.scenario.text": "Low-Code-Orchestrierungsschicht für Zonen, Trigger, Regeln, Zeitpläne, Eskalation, Benachrichtigungen und Multi-Event-Szenarien.",
        "platform.components.factory.text": "Werkzeuge zur Datenerfassung, Dataset-Annotation, Erzeugung synthetischer Beispiele, Modelltraining und Versionsverwaltung.",
        "platform.components.llmVlm.title": "LLM- / VLM-Schicht",
        "platform.components.llmVlm.text": "Aufgabenschnittstelle in natürlicher Sprache und Vision-Language-Verständnis zur Umwandlung geschäftlicher Absicht in KI-Szenarien und Datensätze.",
        "platform.common.cloudHub": "Cloud Hub",
        "platform.components.cloudHub.text": "Zentrales Management von Modellen, Lizenzen, Szenarien, Analytics, Reporting, Multi-Site-Betrieb und Deployment-Workflows.",
        "platform.components.onPrem.title": "On-Prem Runtime",
        "platform.components.onPrem.text": "Lokale KI-Verarbeitung innerhalb der Unternehmensumgebung mit Unterstützung für GPUs, VMS-Integration, Edge-Knoten und sichere Infrastruktur.",
        "platform.architecture.kicker": "Architektur",
        "platform.architecture.title": "Einheitliche Architektur für Eingaben, KI-Verarbeitung und Ausgaben",
        "platform.architecture.lead": "Die Plattform verbindet bestehende Kameras, Mikrofone, Sensoren, VMS und Unternehmenssysteme zu einer KI-Betriebsschicht, die Ereignisse, Alarme, Berichte, Dashboards und Integrationen erzeugt.",
        "platform.factory.title": "Kontinuierliche Erstellung und Verbesserung von KI-Modellen",
        "platform.factory.lead": "AI Factory ist die interne Schleife, mit der neue Modelle erstellt, bestehende verbessert und Analytics an kundenspezifische Umgebungen, Objekte und Kamerawinkel angepasst werden.",
        "platform.factory.main.text": "Die Plattform kombiniert reale Daten, synthetische Generierung, VLM-gestütztes Labeling, Modelltraining und Feedback-Loops zu einem wiederholbaren Prozess zur schnelleren Erstellung neuer KI-Szenarien.",
        "platform.factory.step1.title": "Datenerfassung",
        "platform.factory.step1.text": "Sammelt Beispiele aus Kameras, archivierten Ereignissen, Kundendaten und kontrollierten Testumgebungen.",
        "platform.factory.step2.title": "Synthetische Daten",
        "platform.factory.step2.text": "Erzeugt seltene oder schwer zu erfassende Fälle, um Robustheit zu verbessern und die Startzeit des Modells zu verkürzen.",
        "platform.factory.step3.title": "VLM-Labeling",
        "platform.factory.step3.text": "Nutzt Vision-Language-Modelle für Objektverständnis, Vor-Labeling und Dataset-Validierung.",
        "platform.factory.step4.title": "Training",
        "platform.factory.step4.text": "Trainiert und optimiert KI-Modelle für bestimmte Ereignisse, Standorte, Branchen und Kamerabedingungen.",
        "platform.factory.step5.title": "Model Registry",
        "platform.factory.step5.text": "Speichert Modellversionen, Metriken, Szenarien und Deployment-Konfigurationen in einem kontrollierten System.",
        "platform.factory.step6.title": "Feedback-Loop",
        "platform.factory.step6.text": "Nutzt reale Vorfälle, False Positives und Operator-Validierung zur kontinuierlichen Modellverbesserung.",
        "platform.usecases.kicker": "Beispielszenarien",
        "platform.usecases.title": "Typische KI-Szenarien auf der Plattform",
        "platform.usecases.lead": "Dieselbe Plattformbasis kann einfache und komplexe Event-Analytics-Szenarien für Arbeitssicherheit, Betrieb, Logistik, Retail, HoReCa und Infrastruktur erstellen.",
        "platform.usecases.ppe.title": "PSA-Erkennung",
        "platform.usecases.ppe.text": "Erkennt fehlende Helme, Westen, Masken, Handschuhe, Schutzbrillen und andere vorgeschriebene Schutzausrüstung.",
        "platform.usecases.violations.title": "Verstoß-Erkennung",
        "platform.usecases.violations.text": "Erkennt unsicheres Verhalten, Zutritt zu Sperrbereichen, Perimeterverletzungen und Policy-Verstöße.",
        "platform.usecases.fire.title": "Feuer- und Raucherkennung",
        "platform.usecases.fire.text": "Erkennt Rauch, Feuer und Notfallereignisse in Produktion, Lagern und öffentlichen Bereichen.",
        "platform.usecases.phone.title": "Telefonnutzung",
        "platform.usecases.phone.text": "Kontrolliert Telefonnutzung und Ablenkungen in verbotenen Industrie- oder Betriebszonen.",
        "platform.usecases.people.title": "Personenzählung",
        "platform.usecases.people.text": "Analysiert Belegung, Kundenfluss, Warteschlangen, Personendichte und Arbeitslast standortübergreifend.",
        "platform.usecases.process.title": "Prozessmonitoring",
        "platform.usecases.process.text": "Überwacht Ausrüstung, Produktionsprozesse, operative Engpässe und ungewöhnliche Ereignisse.",
        "platform.deployment.kicker": "Deployment",
        "platform.deployment.title": "Deployment für Enterprise-Infrastruktur",
        "platform.deployment.lead": "STATANLY unterstützt Cloud-, sichere On-Prem-, Edge- und Hybridarchitekturen und ermöglicht KI-Analytics für einzelne Standorte, verteilte Netzwerke oder tausende Kamerastreams.",
        "platform.deployment.cloud.text": "Zentrales Management von Szenarien, Modellen, Analytics, Lizenzen, Ereignissen und Multi-Site-Reporting.",
        "platform.deployment.onPrem.title": "On-Prem",
