        "platform.impact.text": "Plattformwirkung: schnellere Erstellung von KI-Szenarien, einheitliche Event-Analytics statt isolierter Detektoren, kontinuierliche Modellverbesserung und skalierbares Deployment über Unternehmensstandorte und Kameranetze.",
