        "common.more": "Mehr",
        "common.readMore": "Mehr lesen",
        "hero.slide1.title": "Arbeitssicherheit und Verstoßkontrolle",
        "hero.slide1.text": "Kontrolle der Arbeitssicherheit und des Arbeitsschutzes, PSA-Erkennung, Verstoßkontrolle, Notfallerkennung und Überwachung des Anlagenbetriebs",
        "hero.slide2.title": "Verhaltens- und Ereignisanalytik",
        "hero.slide2.text": "Überwachung der Mitarbeiterauslastung, Aufgabenbewertung, Analyse von Personalaktionen sowie Erkennung von Diebstahl und verdächtigen Ereignissen",
        "hero.slide3.title": "Qualitätskontrolle und Produktionsautomatisierung",
        "hero.slide3.text": "Erkennung von Defekten und Ausschuss, Zählung und Klassifizierung auf Förderbändern, Montagekontrolle und Linienautomatisierung",
        "about.kicker": "Über uns",
        "about.title": "Technologien, die sehen, hören und verstehen",
        "about.p1": "Statanly Tech Global entwickelt eine Enterprise-KI-Plattform für Video- und Audioanalytik, ausgelegt für Industrie, Retail, HoReCa, Verkehrsinfrastruktur und Automatisierung von Unternehmensprozessen.",
        "about.p2": "Das Unternehmen bündelt Expertise in Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps und der Entwicklung hochlastfähiger KI-Systeme für Unternehmenskunden.",
        "about.li1": "Mehr als 400 abgeschlossene KI-Projekte für große Industrie- und Geschäftskunden, darunter Metallurgie, Energie, Produktion, Retail und Hospitality.",
        "about.li2": "Eigene KI-Plattform für Ereignisanalytik mit Low-Code-Szenarien, Cloud- und On-Premise-Architektur, BI-Analytik und Modell-Marktplatz.",
        "about.li3": "Ein Team aus Ingenieuren, Data Scientists und Forschern mit Erfahrung in Enterprise-KI-Lösungen und führenden globalen AI/ML-Unternehmen.",
        "about.li4": "Entwicklung branchenspezifischer KI-Ökosysteme, die fertige Modelle, Generative AI, VLM und Werkzeuge zur Erstellung neuer Szenarien für konkrete Geschäftsanforderungen verbinden. Zum Team gehören Absolventen der weltweit führenden technischen Universitäten.",
        "about.platform.p1": "Das Kernprodukt des Unternehmens ist eine universelle KI-Plattform für Ereignisanalytik auf Basis von Computer Vision, Speech Analytics, Large Language Models (LLM), VLM und Generative AI, entwickelt zum Aufbau eines Ökosystems intelligenter Modelle und Szenarien für jede Branche.",
        "about.platform.p2": "Die Plattform verbindet Videostreams, Audiodaten, Ereignisse und Geschäftsprozesse zu einem einheitlichen KI-System für Management, Monitoring und Analytik. Die Architektur ermöglicht sowohl den Einsatz fertiger KI-Module als auch die Erstellung eigener Szenarien, Modelle und Regeln ohne komplexe Entwicklung oder tiefes Machine-Learning-Know-how.",
        "about.platform.p3": "Dank Low-Code-Werkzeugen, VLM und Generative AI können auch nicht-technische Nutzer neue Kontroll-, Automatisierungs- und Analytik-Szenarien per natürlicher Sprache erstellen und die Plattform an ein konkretes Unternehmen, Objekt oder Produktionsverfahren anpassen.",
        "about.platform.p4": "Auf Basis der Plattform entstehen KI-Lösungen für Arbeitssicherheit, Verstoßkontrolle, Analyse der Mitarbeitereffizienz, Produktionsanalytik, Qualitätskontrolle, Retail, HoReCa, Verkehrsinfrastruktur und operative Automatisierung.",
