        "horeca.the.platform.helps.businesses.identify.not.only.isolated": "Die Plattform erkennt nicht nur einzelne Vorfälle, sondern auch versteckte operative Verluste wie lange Wartezeiten, überlastete Bereiche, Regelverstöße, Küchenineffizienz, Ablenkungen des Personals und sinkende Servicequalität.",
        "horeca.most.restaurant.operations.are.still.monitored.manually.the": "Die meisten Restaurantprozesse werden noch manuell überwacht. Die KI-Plattform macht Service, Küche und Personalmanagement zu einem datengetriebenen System mit Echtzeitereignissen und Performance-Analytics.",
