        "privacy.pageTitle": "Политика конфиденциальности",
        "privacy.kicker": "GDPR / защита данных в ЕС",
        "privacy.hero.title": "Политика конфиденциальности",
        "privacy.hero.lead": "Настоящая Политика конфиденциальности объясняет, как Statanly Tech Global собирает, использует, хранит и защищает персональные данные, когда вы посещаете наш сайт, связываетесь с нами, запрашиваете информацию, пользуетесь нашими услугами или взаимодействуете с нашей AI-платформой.",
        "privacy.lastUpdated": "Последнее обновление: 30 мая 2026 г.",
        "privacy.toc.title": "Содержание",
        "privacy.toc.controller": "Контролер данных",
        "privacy.toc.data": "Какие данные мы обрабатываем",
        "privacy.toc.purposes": "Цели и правовые основания",
        "privacy.toc.cookies": "Cookies и аналитика",
        "privacy.toc.sharing": "Передача и трансграничные передачи",
        "privacy.toc.retention": "Сроки хранения",
        "privacy.toc.rights": "Ваши права",
        "privacy.toc.security": "Безопасность",
        "privacy.toc.contacts": "Контакты",
        "privacy.controller.title": "1. Кто мы",
        "privacy.controller.p1": "STATANLY Global разрабатывает enterprise AI-платформу для видео-, аудио- и событийной аналитики. В рамках настоящей Политики конфиденциальности “STATANLY”, “мы”, “нас” или “наш” означает компанию, которая управляет этим сайтом и предоставляет информацию о продуктах и услугах STATANLY.",
        "privacy.controller.p2": "Когда мы собираем персональные данные через этот сайт, формы обратной связи, деловую переписку, запросы демонстрации или маркетинговые взаимодействия, мы обычно выступаем контролером данных. Когда наша платформа развернута у клиента и обрабатывает персональные данные от имени клиента, клиент обычно является контролером, а STATANLY может выступать обработчиком по отдельному соглашению об обработке данных.",
        "privacy.controller.emailTitle": "Контакт по вопросам приватности",
        "privacy.controller.locationTitle": "Локация",
        "privacy.controller.locationText": "Praça do Comércio, 1100-148 Лиссабон, Португалия / Европейский союз",
        "privacy.controller.dpoTitle": "Контакт по защите данных",
        "privacy.controller.dpoText": "Пожалуйста, свяжитесь с нами по email по вопросам конфиденциальности и защиты данных.",
        "privacy.data.title": "2. Персональные данные, которые мы можем обрабатывать",
        "privacy.data.p1": "В зависимости от того, как вы взаимодействуете с нами, мы можем обрабатывать следующие категории персональных данных:",
        "privacy.data.li1": "Деловые контактные данные: имя, компания, должность, email, телефон и страна.",
        "privacy.data.li2": "Информация, которую вы отправляете через формы сайта, email, запросы демонстрации, коммерческие обсуждения или обращения в поддержку.",
        "privacy.data.li3": "Технические данные: IP-адрес, тип браузера, информация об устройстве, примерное местоположение, посещенные страницы, временные метки и данные использования сайта.",
        "privacy.data.li4": "Данные коммуникаций: история переписки, заметки встреч, запросы, обратная связь и коммерческие предпочтения.",
        "privacy.data.li5": "Договорные и транзакционные данные, когда мы вступаем в деловые отношения с вашей организацией.",
        "privacy.purposes.title": "3. Зачем мы обрабатываем персональные данные",
        "privacy.purposes.p1": "Мы обрабатываем персональные данные только при наличии законного основания в соответствии с применимым законодательством о защите данных. Основные цели и основания:",
