        "privacy.basis.legal": "Юридическая обязанность и законные интересы.",
        "privacy.cookies.title": "4. Cookies и похожие технологии",
        "privacy.cookies.p1": "Мы можем использовать cookies и похожие технологии для работы сайта, запоминания пользовательских предпочтений, понимания эффективности сайта и улучшения контента. Когда это требуется законом, мы запрашиваем ваше согласие перед использованием необязательных cookies.",
        "privacy.cookies.p2": "Обычно вы можете управлять cookies через настройки браузера. Отключение некоторых cookies может повлиять на работу сайта.",
        "privacy.sharing.title": "5. Передача персональных данных",
        "privacy.sharing.p1": "Мы не продаем персональные данные. Мы можем передавать персональные данные надежным поставщикам услуг и деловым партнерам, когда это необходимо для работы сайта, предоставления услуг, управления отношениями с клиентами, обработки коммуникаций, хостинга инфраструктуры, аналитики, выполнения юридических обязательств или защиты наших прав.",
        "privacy.sharing.p2": "Если персональные данные передаются за пределы Европейской экономической зоны, мы используем соответствующие гарантии, когда это требуется, например решения об адекватности, стандартные договорные положения или другие законные механизмы передачи.",
        "privacy.retention.title": "6. Как долго мы храним персональные данные",
        "privacy.retention.p1": "Мы храним персональные данные только столько, сколько необходимо для целей, описанных в этой Политике конфиденциальности, включая ответы на запросы, ведение деловых записей, предоставление услуг, выполнение юридических обязательств, разрешение споров и исполнение соглашений.",
        "privacy.retention.p2": "Сроки хранения могут различаться в зависимости от типа данных, характера наших отношений с вами или вашей организацией, требований закона и законных бизнес-потребностей.",
        "privacy.rights.title": "7. Ваши права в области защиты данных",
        "privacy.rights.p1": "В соответствии с применимым законодательством у вас могут быть следующие права в отношении ваших персональных данных:",
        "privacy.rights.li1": "Право на доступ к вашим персональным данным.",
        "privacy.rights.li2": "Право на исправление неточных или неполных данных.",
        "privacy.rights.li3": "Право на удаление персональных данных в определенных случаях.",
        "privacy.rights.li4": "Право на ограничение обработки.",
        "privacy.rights.li5": "Право возражать против обработки на основании законных интересов или прямого маркетинга.",
        "privacy.rights.li6": "Право на переносимость данных, если обработка основана на согласии или договоре и осуществляется автоматизированными средствами.",
        "privacy.rights.li7": "Право отозвать согласие в любой момент, если обработка основана на согласии.",
        "privacy.rights.li8": "Право подать жалобу в компетентный орган по защите данных.",
        "privacy.rights.note": "Чтобы реализовать свои права, напишите нам на hello@statanly.eu. Перед ответом на запрос нам может потребоваться подтвердить вашу личность.",
        "privacy.security.title": "8. Безопасность",
        "privacy.security.p1": "Мы применяем организационные и технические меры, направленные на защиту персональных данных от случайного или незаконного уничтожения, потери, изменения, несанкционированного раскрытия или доступа. Такие меры могут включать контроль доступа, защищенную инфраструктуру, шифрование там, где это уместно, журналы событий, резервное копирование и внутренние правила безопасности.",
        "privacy.security.p2": "Ни один способ передачи или хранения данных не является полностью безопасным. Мы постоянно работаем над повышением безопасности наших систем и процессов.",
        "privacy.ai.title": "9. AI-платформа и клиентские развертывания",
        "privacy.ai.p1": "Продукты STATANLY могут быть развернуты в инфраструктуре клиентов для анализа видео, аудио, операционных событий или других источников данных. В таких случаях клиент обычно определяет цели и средства обработки и отвечает за уведомления, наличие правовых оснований и настройку системы в соответствии с применимым законодательством.",
        "privacy.ai.p2": "Когда STATANLY обрабатывает персональные данные от имени клиента, мы делаем это по инструкциям клиента и на основании соответствующего соглашения об обработке данных.",
        "privacy.changes.title": "10. Изменения в этой Политике конфиденциальности",
        "privacy.changes.p1": "Мы можем время от времени обновлять эту Политику конфиденциальности, чтобы отражать изменения на сайте, в услугах, технологиях, законодательных требованиях или бизнес-процессах. Актуальная версия будет опубликована на этой странице.",
        "privacy.contacts.title": "11. Связаться с нами",
        "privacy.contacts.p1": "Если у вас есть вопросы об этой Политике конфиденциальности или о том, как мы обрабатываем персональные данные, свяжитесь с нами:",
        "privacy.contacts.email": "Email",
        "privacy.contacts.website": "Сайт",
