        "malls.hero.title": "AI-платформа для торговых и бизнес-центров",
        "malls.hero.subtitle": "Подсчет людей, выявление посторонних предметов, детекция дыма и огня, драк, конфликтов и скоплений людей в единой AI-платформе мониторинга.",
        "malls.meta.people": "Подсчет людей",
        "malls.meta.flow": "Аналитика потоков и зон",
        "malls.meta.smoke": "Детекция дыма и огня",
        "malls.meta.conflict": "Выявление драк и конфликтов",
        "malls.meta.objects": "Выявление посторонних предметов",
        "malls.meta.crowd": "Мониторинг скоплений",
        "malls.intro.p1": "AI-платформа для торговых центров превращает существующие камеры наблюдения в систему операционного контроля в реальном времени для анализа потоков посетителей, инцидентов безопасности, заторов и качества сервиса.",
        "malls.intro.p2": "Платформа выявляет аномальные скопления людей, оставленные предметы, риски дыма и огня, агрессивное поведение, драки, нарушения зон доступа и узкие места в потоках посетителей.",
        "malls.insight.text": "Крупные общественные пространства по-прежнему зависят от разрозненного видеонаблюдения. AI-платформа превращает мониторинг торговых и бизнес-центров в единую систему на базе аналитики посетителей, событий в реальном времени и операционной аналитики.",
        "malls.cap.title": "AI-возможности для торговых и бизнес-центров",
        "malls.cap.lead": "Платформа объединяет аналитику безопасности, мониторинг потоков посетителей и выявление инцидентов, помогая управлять атриумами, коридорами, входами, фудкортами, парковочными переходами и общими зонами бизнес-центров.",
        "malls.cap.people.title": "Подсчет людей и аналитика зон",
        "malls.cap.people.text": "Подсчет посетителей в реальном времени по зонам, этажам, входам, эскалаторным зонам и ключевым коридорам с тепловыми картами и показателями заполняемости.",
        "malls.cap.crowd.title": "Плотность скоплений и заторы",
        "malls.cap.crowd.text": "Выявление переполненных зон, необычного образования очередей и заторов у входов, фудкортов, лифтов и эвакуационных маршрутов.",
        "malls.cap.conflict.title": "Выявление драк и конфликтов",
        "malls.cap.conflict.text": "Автоматическое выявление агрессивного поведения, драк, нарушений общественного порядка и сценариев эскалации для быстрой реакции службы безопасности.",
        "malls.cap.fire.title": "Дым, огонь и риски безопасности",
        "malls.cap.fire.text": "Ранняя детекция дыма и открытого огня в общих зонах, сервисных коридорах и технических помещениях с немедленными оповещениями.",
        "malls.cap.objects.title": "Посторонние и оставленные предметы",
        "malls.cap.objects.text": "Выявление оставленных сумок, бесхозных объектов и посторонних предметов в проходах, холлах и общественных пространствах.",
        "malls.cap.performance.title": "Эффективность ТЦ и бизнес-центра",
        "malls.cap.performance.text": "Объективная аналитика часов пик, заполняемости по зонам, трафика рядом с арендаторами и использования сервисных зон.",
