        "beauty.intro.p1": "AI-платформа для салонов красоты превращает существующие камеры в систему операционного контроля в реальном времени для этапов обслуживания, активности персонала, санитарных стандартов, клиентского опыта и событий безопасности.",
        "beauty.intro.p2": "Платформа выявляет задержки обслуживания, оставленные без контроля зоны ресепшена, подозрительную активность, риски огня и дыма, нарушения санитарных процедур, проблемы загрузки персонала и узкие места клиентского сервиса.",
        "beauty.insight.text": "AI превращает салон красоты в измеримую сервисную среду: каждый этап обслуживания, действие персонала, событие безопасности и показатель клиентского опыта становится объективными данными для улучшения качества.",
        "beauty.cap.kicker": "AI-возможности",
        "beauty.cap.title": "AI-возможности для салонов красоты",
        "beauty.cap.lead": "Платформа объединяет контроль качества сервиса, мониторинг безопасности, предотвращение хищений, выявление пожарных рисков, аналитику персонала и улучшение клиентского опыта в одном операционном слое.",
