        "beauty.cap.safety.title": "Безопасность и соответствие",
        "beauty.cap.safety.text": "Мониторинг процедур безопасности, санитарных стандартов и соблюдения правил в зонах салона.",
        "beauty.cap.theft.title": "Предотвращение хищений",
