        "beauty.cap.fire.title": "Детекция огня и дыма",
        "beauty.cap.fire.text": "Раннее выявление дыма, рисков пожара и небезопасного использования оборудования с мгновенными оповещениями для управляющих.",
        "beauty.cap.staff.title": "Управление персоналом",
        "beauty.cap.staff.text": "Мониторинг посещаемости, продуктивности, распределения загрузки, простоев и сервисной дисциплины персонала.",
        "beauty.cap.quality.title": "Повышение качества сервиса",
