        "platform.strip.integration.title": "Интеграция с VMS / enterprise-системами",
        "platform.strip.integration.text": "Подключение камер, VMS, SCADA, ERP, СКУД, BI и API.",
        "platform.pipeline.kicker": "Как это работает",
        "platform.pipeline.title": "От задачи на естественном языке до развернутого AI-сценария",
        "platform.pipeline.lead": "Ключевая идея платформы проста: пользователь описывает задачу мониторинга естественным языком — платформа автоматически строит AI-pipeline, готовит данные, создает сценарий и разворачивает аналитику на камеры и инфраструктуру.",
        "platform.pipeline.note": "Пользователю не нужна AI-экспертиза: STATANLY превращает запрос вроде «детектировать сотрудников без касок» или «найти дым и огонь» в подготовку данных, создание модели, сценарную логику и развертывание.",
        "platform.components.kicker": "Компоненты платформы",
        "platform.components.title": "Ключевые компоненты платформы",
        "platform.components.lead": "STATANLY — это не просто набор детекторов. Это полноценный платформенный слой для создания и эксплуатации AI-событийной аналитики в enterprise-инфраструктуре.",
        "platform.components.multimodal.title": "Мультимодальная событийная аналитика",
        "platform.components.multimodal.text": "Видео, аудио, датчики и метаданные обрабатываются вместе для выявления событий, нарушений, операционных рисков и отклонений процессов.",
        "platform.components.scenario.text": "Low-code слой оркестрации для зон, триггеров, правил, расписаний, эскалаций, уведомлений и мультисобытийных сценариев.",
        "platform.components.factory.text": "Инструменты для сбора данных, разметки датасетов, генерации синтетических примеров, обучения моделей и управления версиями.",
        "platform.components.llmVlm.title": "LLM / VLM слой",
        "platform.components.llmVlm.text": "Интерфейс постановки задач на естественном языке и визуально-языковое понимание для превращения бизнес-намерения в AI-сценарии и датасеты.",
        "platform.common.cloudHub": "Cloud Hub",
        "platform.components.cloudHub.text": "Централизованное управление моделями, лицензиями, сценариями, аналитикой, отчетностью, мультисайтовыми операциями и workflow развертывания.",
        "platform.components.onPrem.title": "On-Prem Runtime",
        "platform.components.onPrem.text": "Локальная AI-обработка внутри периметра предприятия с поддержкой GPU, интеграции с VMS, edge-узлов и защищенной инфраструктуры.",
        "platform.architecture.kicker": "Архитектура",
        "platform.architecture.title": "Единая архитектура для входных данных, AI-обработки и выходов",
        "platform.architecture.lead": "Платформа подключает существующие камеры, микрофоны, датчики, VMS и корпоративные системы в единый AI operating layer, который формирует события, уведомления, отчеты, дашборды и интеграции.",
        "platform.factory.title": "Непрерывное создание и улучшение AI-моделей",
        "platform.factory.lead": "AI Factory — внутренний цикл платформы, который позволяет создавать новые модели, улучшать существующие и адаптировать аналитику под конкретные объекты, среды и ракурсы камер заказчика.",
        "platform.factory.main.text": "Платформа объединяет реальные данные, синтетическую генерацию, VLM-разметку, обучение моделей и feedback loop в повторяемый процесс ускоренного создания новых AI-сценариев.",
        "platform.factory.step1.title": "Сбор данных",
        "platform.factory.step1.text": "Сбор примеров с камер, архивных событий, данных заказчика и контролируемых тестовых сред.",
        "platform.factory.step2.title": "Синтетические данные",
        "platform.factory.step2.text": "Генерация редких или сложных для сбора случаев для повышения устойчивости и сокращения срока запуска модели.",
        "platform.factory.step3.title": "VLM-разметка",
