        "platform.factory.step6.title": "Feedback loop",
        "platform.factory.step6.text": "Использование реальных инцидентов, ложных срабатываний и валидации операторов для постоянного улучшения моделей.",
        "platform.usecases.kicker": "Примеры сценариев",
