        "platform.usecases.lead": "Одна и та же платформенная основа позволяет создавать простые и сложные сценарии событийной аналитики для промышленной безопасности, операций, логистики, ритейла, HoReCa и инфраструктуры.",
        "platform.usecases.ppe.title": "Детекция СИЗ",
