        "platform.usecases.process.title": "Мониторинг процессов",
        "platform.usecases.process.text": "Мониторинг оборудования, производственных процессов, операционных узких мест и аномальных событий.",
        "platform.deployment.kicker": "Развертывание",
        "platform.deployment.title": "Развертывание для enterprise-инфраструктуры",
        "platform.deployment.lead": "STATANLY поддерживает cloud, защищенную on-premise, edge и гибридную архитектуру, позволяя разворачивать AI-аналитику на одной площадке, распределенной сети или тысячах видеопотоков.",
        "platform.deployment.cloud.text": "Централизованное управление сценариями, моделями, аналитикой, лицензиями, событиями и мультисайтовой отчетностью.",
        "platform.deployment.onPrem.title": "On-Prem",
