        "platform.impact.text": "Эффект платформы: быстрое создание AI-сценариев, единая событийная аналитика вместо разрозненных детекторов, постоянное улучшение моделей и масштабируемое развертывание на площадках и сетях камер.",
        "platform.tags.multimodal": "Мультимодальный AI",
