        "common.more": "Подробнее",
        "common.readMore": "Подробнее",
        "hero.slide1.title": "Промышленная безопасность и контроль нарушений",
        "hero.slide1.text": "Контроль промышленной безопасности и охраны труда, распознавание СИЗ, выявление нарушений, чрезвычайных ситуаций и мониторинг оборудования",
        "hero.slide2.title": "Анализ поведения людей и событий",
        "hero.slide2.text": "Мониторинг вовлеченности сотрудников, оценка выполнения задач, анализ действий персонала, выявление краж и подозрительных событий",
        "hero.slide3.title": "Контроль качества и автоматизация производства",
        "hero.slide3.text": "Выявление дефектов и брака, подсчет и классификация объектов на конвейере, контроль точности сборки и автоматизация производственной линии",
        "about.kicker": "О компании",
        "about.title": "Технологии, которые видят, слышат и понимают",
        "about.p1": "Statanly Tech Global — разработчик enterprise AI-платформы для видео- и аудиоаналитики, предназначенной для промышленности, ритейла, HoReCa, транспортной инфраструктуры и автоматизации корпоративных процессов.",
        "about.p2": "Компания объединяет экспертизу в области Computer Vision, Speech Analytics, Large Language Models, Generative AI, MLOps и построения высоконагруженных AI-систем для корпоративного сектора.",
        "about.li1": "Более 400 реализованных AI-проектов для крупных промышленных и коммерческих заказчиков, включая металлургию, энергетику, производство, ритейл и сферу гостеприимства.",
        "about.li2": "Собственная AI-платформа событийной аналитики с поддержкой low-code сценариев, облачной и on-premise архитектуры, BI-аналитики и marketplace моделей.",
        "about.li3": "Команда инженеров, data scientists и исследователей с опытом разработки enterprise AI-решений и опытом работы в ведущих мировых AI/ML-компаниях.",
        "about.li4": "Разработка отраслевых AI-экосистем, объединяющих готовые модели, генеративный ИИ, VLM и инструменты создания новых сценариев под задачи конкретного бизнеса. В команде — выпускники лучших технических университетов мира.",
        "about.platform.p1": "Ключевой продукт компании — мультимодальная ИИ-платформа событийной аналитики, построенная на базе технологий компьютерного зрения, речевой аналитики, больших языковых моделей (LLM), VLM и генеративного ИИ, предназначенная для создания экосистемы интеллектуальных моделей и сценариев под задачи любой отрасли.",
        "about.platform.p2": "Главная идея платформы — упростить создание новых AI-сценариев: пользователь формулирует задачу обычным языком, а система помогает превратить её в работающий сценарий мониторинга, детекции или анализа событий. Это может быть контроль нарушения техники безопасности, отклонения в производственном процессе, действия персонала, дефекта продукции, очереди, простоя оборудования или другого нестандартного события.",
        "about.platform.p3": "Платформа объединяет видеопотоки, аудиоданные, события и бизнес-процессы в единую AI-среду. В ней можно использовать готовые модули, настраивать правила событийной аналитики, подключать новые источники данных, дообучать модели и адаптировать сценарии под конкретное предприятие, объект или производственный процесс.",
        "about.platform.p4": "На базе платформы развиваются AI-решения для промышленной безопасности, контроля нарушений, анализа эффективности персонала, производственной аналитики, контроля качества, ритейла, HoReCa, транспортной инфраструктуры и автоматизации операционных процессов.",
