        "horeca.the.platform.helps.businesses.identify.not.only.isolated": "Платформа помогает выявлять не только отдельные инциденты, но и скрытые операционные потери: долгие ожидания, перегруженные зоны, нарушения стандартов, неэффективность кухни, отвлечения персонала и снижение качества сервиса.",
        "horeca.most.restaurant.operations.are.still.monitored.manually.the": "Большая часть ресторанных процессов всё еще контролируется вручную. AI-платформа переводит сервис, кухню и персонал в систему объективных данных, событий в реальном времени и аналитики эффективности.",
