        "horeca.daily.losses.appear.because.of.inefficient.processes.staff": "Ежедневные потери возникают из-за неэффективных процессов, ошибок персонала и отсутствия объективного операционного контроля. В зале это означает долгие ожидания гостей, пустые или грязные столы, очереди и упущенные возможности допродаж. На кухне и в зоне выдачи — задержки, ошибки сборки заказов, возвраты и потери продукта. В управлении персоналом — простои, отвлечения, непоследовательное соблюдение стандартов и неравномерную нагрузку.",
